body.query:
query OmniSearch(
  $resourcePredicate: Predicate
  $resourceKeywordPredicate: Predicate
  $taxonQuery: TaxonSearchInput
  $datasetQuery: DatasetSearchInput
  $q: String!
) {
  organizationSearch(isEndorsed: true, q: $q, limit: 3) {
    limit
    count
    offset
    results {
      key
      title
      created
      country
      logoUrl
      excerpt
    }
  }
  datasetSearch(query: $datasetQuery) {
    count
    limit
    offset
    results {
      ...DatasetStubResult
    }
  }
  taxonSearch(query: $taxonQuery, limit: 3) {
    count
    offset
    endOfRecords
    results {
      ...TaxonSearchResultCard
    }
  }

  resourceSearch(predicate: $resourcePredicate, q: $q, searchable: true) {
    documents(size: 5) {
      from
      size
      total
      results {
        ...ResourceSearchResult
      }
    }
  }

  resourceKeywordSearch: resourceSearch(
    predicate: $resourceKeywordPredicate
    q: $q
    searchable: true
  ) {
    documents(size: 5) {
      from
      size
      total
      results {
        ...ResourceSearchResult
      }
    }
  }
}

fragment DatasetStubResult on DatasetSearchStub {
  key
  title
  excerpt
  type
  publishingOrganizationTitle
}

fragment TaxonSearchResultCard on TaxonResult {
  vernacularName(language: "eng") {
    vernacularName
  }
  ...TaxonSearchResultDetails
  acceptedTaxon {
    taxonID
    label
    datasetKey
    scientificName
    taxonRank
    taxonomicStatus
    parentTree {
      scientificName
      taxonID
    }
    mapCapabilities {
      total
    }
  }
}

fragment TaxonSearchResultDetails on TaxonResult {
  taxonID
  label
  datasetKey
  scientificName
  taxonRank
  taxonomicStatus
  parentTree {
    scientificName
    taxonID
  }
  mapCapabilities {
    total
  }
}

fragment ResourceSearchResult on Resource {
  __typename
  ... on Composition {
    ...CompositionResult
  }
  ... on News {
    ...NewsResult
  }
  ... on Article {
    ...ArticleResult
  }
  ... on DataUse {
    ...DataUseResult
  }
  ... on MeetingEvent {
    ...EventResult
  }
  ... on GbifProject {
    ...ProjectResult
  }
  ... on Programme {
    ...ProgrammeResult
  }
  ... on Tool {
    ...ToolResult
  }
  ... on Document {
    ...DocumentResult
  }
  ... on Document {
    ...DocumentResult
  }
  ... on NetworkProse {
    ...NetworkProseResult
  }
  ... on Help {
    ...HelpResult
  }
}

fragment CompositionResult on Composition {
  id
  title
  excerpt
  urlAlias
  primaryImage {
    ...ResultCardImage
  }
}

fragment ResultCardImage on AssetImage {
  file {
    url: thumbor(width: 180, height: 120)
  }
}

fragment NewsResult on News {
  id
  title
  excerpt
  primaryImage {
    ...ResultCardImage
  }
  createdAt
}

fragment ArticleResult on Article {
  id
  title
  excerpt
  urlAlias
  primaryImage {
    ...ResultCardImage
  }
}

fragment DataUseResult on DataUse {
  id
  title
  excerpt
  primaryImage {
    ...ResultCardImage
  }
  createdAt
}

fragment EventResult on MeetingEvent {
  id
  title
  excerpt
  country
  location
  venue
  start
  end
  primaryLink {
    url
  }
  gbifsAttendee
  allDayEvent
}

fragment ProjectResult on GbifProject {
  id
  title
  excerpt
  primaryImage {
    ...ResultCardImage
  }
  createdAt
  programme {
    id
    title
  }
  purposes
}

fragment ProgrammeResult on Programme {
  id
  title
  excerpt
  primaryImage {
    ...ResultCardImage
  }
}

fragment ToolResult on Tool {
  id
  title
  excerpt
  primaryLink {
    url
  }
  primaryImage {
    ...ResultCardImage
  }
}

fragment DocumentResult on Document {
  id
  title
  excerpt
}

fragment NetworkProseResult on NetworkProse {
  id
  title
  excerpt
  networkKey
  primaryImage {
    ...ResultCardImage
  }
  createdAt
}

fragment HelpResult on Help {
  id
  identifier
  title
  body
  excerpt
}
